def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_c = my.count('C')
    opp_c = opp.count('C')
    opp_d = n - opp_c

    last_my = my[-1]
    last_opp = opp[-1]

    # Endgame exploitation: against a highly cooperative opponent,
    # defect in the final rounds to grab 5s instead of 3s.
    if n >= 96:
        if opp_d <= 3:
            return 'D'
        if n >= 99:
            return 'D' if last_opp == 'C' else 'C'

    # Always-defect detector: punish hard, don't waste rounds probing.
    if n >= 6:
        recent6_opp_d = sum(1 for b in opp[-6:] if b == 'D')
        if recent6_opp_d == 6:
            return 'D'

    # Immediate retaliation: if opponent just defected, respond with D.
    # But avoid locking into DD by forgiving rarely when they look contrite.
    if last_opp == 'D':
        # Opponent defected last. Check streak length.
        streak = 0
        for b in reversed(opp):
            if b == 'D':
                streak += 1
            else:
                break
        if streak >= 2:
            # Extended punishment, but probe rarely to escape DD.
            if streak >= 4 and n > 30:
                recent_opp_c = sum(1 for b in opp[-8:] if b == 'C')
                if recent_opp_c == 0 and rng.random() < 0.12:
                    return 'C'
            return 'D'
        # Single defection: classic TFT retaliation.
        # If opponent's overall cooperation is high, occasionally forgive sooner.
        if opp_c * 4 >= n * 3:
            # mostly cooperative; forgive with small chance to reset
            if n > 25 and rng.random() < 0.10:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round, return to C (recovery after punishment).
    if last_my == 'D':
        return 'C'

    # Opponent cooperated. Count recent cooperation.
    window = opp[-8:] if n >= 8 else opp
    wc = window.count('C')
    wl = len(window)

    # If opponent has been highly cooperative, mostly cooperate but
    # test/probe occasionally to punish over-cooperation exploitation.
    if wc >= wl - 1:
        if n > 20 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # If recent opponent cooperation is mediocre, be more cautious.
    if wc * 3 < wl:
        return 'D' if rng.random() < 0.6 else 'C'

    return 'C'
